#include <vector>
#include <algorithm>

using namespace std;

class Solution {
public:
    int maxSumRangeQuery(vector<int>& nums, vector<vector<int>>& requests) {
        const int MOD = 1e9 + 7;
        int n = nums.size();
        vector<int> freq(n + 1);
        for (auto& r : requests) {
            freq[r[0]]++;
            freq[r[1] + 1]--;
        }

        for (int i = 1; i < n; ++i)
            freq[i] += freq[i - 1];
        freq.pop_back();

        sort(nums.begin(), nums.end());
        sort(freq.begin(), freq.end());

        long res = 0;
        for (int i = 0; i < n; ++i)
            res = (res + (long)nums[i] * freq[i]) % MOD;
        return res;
    }
};
